#!/bin/sh
# Listening TCP ports as JSON: [{"port":5432,"command":"postgres","pid":812}, …]
# TailApps' own process ($TAILAPPS_PID) is left out: apps can't stop TailApps.
# lsof on a Mac (and on Linux when it's installed), else ss on Linux, which only names your own processes.
lsof=/usr/sbin/lsof
[ -x "$lsof" ] || lsof=$(command -v lsof)
if [ -n "$lsof" ]; then
  "$lsof" -nP -iTCP -sTCP:LISTEN -F pcn 2>/dev/null | awk -v self="$TAILAPPS_PID" '
  /^p/ { pid = substr($0, 2); skip = (pid == self) }
  /^c/ { cmd = substr($0, 2); gsub(/["\\]/, "", cmd) }
  /^n/ && !skip {
    port = substr($0, 2); sub(/.*:/, "", port)
    key = pid ":" port
    if (!(key in seen)) {
      seen[key] = 1
      printf "%s{\"port\":%s,\"command\":\"%s\",\"pid\":%s}", (count++ ? "," : "["), port, cmd, pid
    }
  }
  END { print (count ? "]" : "[]") }'
elif command -v ss >/dev/null 2>&1; then
  ss -Hltnp 2>/dev/null | awk -v self="$TAILAPPS_PID" '
  {
    port = $4; sub(/.*:/, "", port)
    cmd = ""; pid = 0
    if (match($0, /users:\(\("[^"]*",pid=[0-9]+/)) {
      s = substr($0, RSTART + 9, RLENGTH - 9); cmd = s; sub(/".*/, "", cmd); pid = s; sub(/.*pid=/, "", pid)
      gsub(/["\\]/, "", cmd)
    }
    if (pid == self && pid != 0) next
    key = pid ":" port
    if (!(key in seen)) {
      seen[key] = 1
      printf "%s{\"port\":%s,\"command\":\"%s\",\"pid\":%s}", (count++ ? "," : "["), port, (cmd == "" ? "?" : cmd), pid
    }
  }
  END { print (count ? "]" : "[]") }'
else
  echo "Needs lsof or ss to list ports" >&2
  exit 1
fi
